/* NOTE: `k` and the output byte are volatile on purpose.  Without that the
 * optimizer happily pre-computes the whole keystream for a short string and
 * emits the plaintext as code immediates ("cs2." / "exe\0" showed up in the
 * image exactly this way).  volatile keeps the decode a runtime operation, so
 * the literal only ever exists in a kernel buffer. */
static void cs2_str_dec(const unsigned char* enc, unsigned int n, unsigned int s0,
                        unsigned char* out)
{
    volatile unsigned int k = s0;
    unsigned int i;
    for (i = 0; i < n; i++) {
        k = k * 1103515245u + 12345u;
        ((volatile unsigned char*)out)[i] =
            (unsigned char)(enc[i] ^ (unsigned char)((k >> 16) & 0xFFu));
    }
    out[n] = 0;
    out[n + 1] = 0;
}

