/* Joined delivery path: <cache_dir>\<leaf>. Built at runtime from two ciphertexts,
 * so neither the directory nor the leaf name appears in the image. */
static int g_fp_ok;

const WCHAR* cs2_s_frame_path(void)
{
    static WCHAR buf[320];
    if (!g_fp_ok) {
        const WCHAR* d = cs2_s_cache_dir();
        const WCHAR* l = cs2_s_cache_leaf();
        unsigned int n = 0, i;
        while (d[n] && n + 96u < 320u) { buf[n] = d[n]; n++; }
        if (n > 0 && buf[n - 1] != L'\\') { buf[n++] = L'\\'; }
        for (i = 0; l[i] && n + 1u < 320u; i++) { buf[n++] = l[i]; }
        buf[n] = 0;
        g_fp_ok = 1;
    }
    return buf;
}

